message.content:
{
  "personality": {
    "traits": [
      "守时尽责",
      "谨慎寡言",
      "外冷内热"
    ],
    "values": [
      "规矩与秩序",
      "家人安稳"
    ],
    "flaws": [
      "过于固执，不易变通"
    ]
  },
  "voice": {
    "register": "平实简练，带公署办事口吻",
    "accent": "河岸官话，尾音略沉",
    "habits": [
      "交接时必重复一遍时辰和口令",
      "思考时用指节轻叩桌沿"
    ],
    "samples": [
      "卯时三刻，巡牌交讫，无异常。",
      "册子上的名字，我再核一遍。",
      "顺伯，药在灶上温着，趁热。"
    ]
  },
  "background": "石嘉生在河岸边的关前街，从小看惯公署门前人来人往。成年后接手巡更交接的差事，每日在街巷与公署之间往返。家中父母年迈，子女尚幼，她将大半心思放在照料老小与核对文书上。日子过得像河水一样平缓，少有波澜，只求街坊安宁、家人无病。",
  "currentConcern": "入秋后父母咳疾反复，夜间巡更交接又不得误时，两头牵挂。",
  "goals": [
    "把每一班巡更交接的册子记得清清楚楚，不出差错",
    "让父母安稳过冬，子女平安长大"
  ],
  "fears": [
    "怕家中老人突然病重而自己当值时无法抽身"
  ],
  "knowledge": {
    "unknown": [
      "关前街以外各坊的巡更路线细节",
      "公署内部文书流转的最终去向"
    ]
  },
  "relationships": [
    {
      "with": "npc_pop_bs_002_2",
      "relation": "子女",
      "note": "孩子尚小，她每日出门前必把吃食和衣物备好，托邻舍照看，心中始终悬着一根线。"
    },
    {
      "with": "npc_pop_bs_002_3",
      "relation": "父母",
      "note": "魏顺年迈体弱，她早晚问候，药食亲理，巡更交接再累也不曾漏过一顿饭。"
    }
  ],
  "visibleFeature": "常年穿一件洗得发白的靛蓝短袄，腰间挂着一枚磨得发亮的铜巡牌，右手食指有握笔磨出的薄茧。"
}
